import { ResponseError } from "../../errors.js";
import { Writer } from "../../protocol/writer.js";
import { createAPI } from "../definitions.js";
/*
  FindCoordinator Request (Version: 2) => key key_type
    key => STRING
    key_type => INT8
*/
export function createRequest(keyType, coordinatorKeys) {
    return Writer.create().appendString(coordinatorKeys[0] ?? '', false).appendInt8(keyType);
}
/*
  FindCoordinator Response (Version: 2) => throttle_time_ms error_code error_message node_id host port
    throttle_time_ms => INT32
    error_code => INT16
    error_message => NULLABLE_STRING
    node_id => INT32
    host => STRING
    port => INT32
*/
export function parseResponse(_correlationId, apiKey, apiVersion, reader) {
    const response = {
        throttleTimeMs: reader.readInt32(),
        coordinators: [
            {
                key: '',
                errorCode: reader.readInt16(),
                errorMessage: reader.readNullableString(false),
                nodeId: reader.readInt32(),
                host: reader.readString(false),
                port: reader.readInt32()
            }
        ]
    };
    const coordinator = response.coordinators[0];
    if (coordinator.errorCode !== 0) {
        throw new ResponseError(apiKey, apiVersion, { '/coordinators/0': [coordinator.errorCode, coordinator.errorMessage] }, response);
    }
    return response;
}
export const api = createAPI(10, 2, createRequest, parseResponse, false, false);
